source='Unverified reference lead for independent check: OpenStax Biology 2e, ecology and populations, https://openstax.org/details/books/biology-2e . Exact claim-specific sources have not been verified.'
T='''"use client";
import { useRef, useState } from "react";
import { Lesson } from "@/kit/Lesson";
import { Control, Row } from "@/kit/controls";
const model=__MODEL__;
export default function Demo({slug}:{slug:string}){
 const [seen,setSeen]=useState([false,false]); const seenRef=useRef([false,false]);
 function open(i:0|1,interact:()=>void){if(seenRef.current[i])return;seenRef.current[i]=true;setSeen([...seenRef.current]);interact();}
 return <Lesson slug={slug} predict={{question:model.question,options:model.options,answer:model.answer}} minInteractions={2} exploreHint="Open both panels and compare the evidence." reveal={()=><p>{model.explanation}</p>}>
 {({locked,interact})=><div><svg viewBox="0 0 340 150" className="stage-svg" role="img" aria-label={seen[0]&&seen[1]?model.explanation:"Two evidence panels, hidden before inspection."}>
 <rect x="4" y="4" width="154" height="140" rx="12" fill="var(--bg-2)" stroke="var(--line)"/><rect x="182" y="4" width="154" height="140" rx="12" fill="var(--bg-2)" stroke="var(--line)"/>
 <g transform="translate(6 8)">{seen[0]?<g>__A__</g>:<text x="75" y="75" textAnchor="middle" fill="var(--muted)" fontSize="14">Panel A</text>}</g><g transform="translate(184 8)">{seen[1]?<g>__B__</g>:<text x="75" y="75" textAnchor="middle" fill="var(--muted)" fontSize="14">Panel B</text>}</g></svg>
 <Row><Control style={{minHeight:44,minWidth:44}} disabled={locked||seen[0]} onClick={()=>open(0,interact)}>Open A</Control><Control style={{minHeight:44,minWidth:44}} disabled={locked||seen[1]} onClick={()=>open(1,interact)}>Open B</Control></Row><p style={{fontSize:"0.8rem",color:"var(--muted)",textAlign:"center",margin:"4px 0"}}>Illustrative scenario</p></div>}</Lesson>;
}
'''
for c in C:
 shift=c['id']%3;opt=c['options'][shift:]+c['options'][:shift];ro=c['ro'][shift:]+c['ro'][:shift]
 model={'question':c['q'],'options':opt,'answer':opt.index(c['options'][c['answer']]),'explanation':c['why']}
 meta={'slug':c['slug'],'title':c['title'],'hook':c['hook'],'domain':'life','concept':c['slug'],'status':'draft','durationSec':60,'owner':{'categoryManager':'cm-life','builder':'demo-builder'},'learner':{'knows':['Animals interact with other organisms and their surroundings.'],'doesNotKnow':[c['q']]},'misconception':'One observation or model rule gives a complete answer about nature.','objective':c['q'],'claims':[{'id':f"life.{c['slug']}.c1",'text':c['q']+' '+c['why'],'support':'source','source':source,'status':'unverified'},{'id':f"life.{c['slug']}.c2",'text':'The panels depict a simplified illustrative scenario, not observations or measurements of real animals.','support':'convention','source':'Diagram convention and stipulated model.','status':'unverified'},{'id':f"life.{c['slug']}.c3",'text':c['rq']+' '+c['rw'],'support':'source','source':source,'status':'unverified'}],'confidence':'','recall':{'question':c['rq'],'options':ro,'answer':ro.index(c['ro'][0]),'why':c['rw']},'evidence':{'qa':[],'simulatedLearner':[],'pairwise':[],'humanLearners':[]},'version':1}
 if c['id'] in (467,475):
  meta['claims'].append({'id':f"life.{c['slug']}.c4",'text':('The time intervals are placed on an illustrative clock from 0 to 24.' if c['id']==467 else 'In the toy display, 12 food units shared by 4 or 6 animals gives 3 or 2 units each; the storm fraction is stipulated as one half in both.'),'support':'convention','source':'Stated model and arithmetic.','status':'unverified'})
 p=root/c['slug'];p.mkdir(parents=True);(p/'Demo.tsx').write_text(T.replace('__MODEL__',json.dumps(model,ensure_ascii=False,indent=2)).replace('__A__',c['a']).replace('__B__',c['b']));(p/'meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n')
Path('company/reviews/zoology-ecology-second/manifest.json').write_text(json.dumps([{'plan_id':c['id'],'slug':c['slug']} for c in C],indent=2)+'\n')
print(f'Generated {len(C)} draft lessons')
